// Field names (event, message-id) confirmed against Brevo's public webhook
// docs. UNVERIFIED: Brevo's send-email API returns a 'messageId' (e.g.
// '<xxx@smtp-relay.brevo.com>' or similar), while the webhook event carries
// 'message-id' — confirm these are actually the same value/format on a real
// account before trusting the match; if they differ, fall back to matching
// by recipient email + most recent 'sent' row instead (see the WhatsApp
// reply workflow for that fallback pattern).
const body = $json.body ?? $json;
const providerMessageId = body['message-id'] ?? body.message_id ?? null;
const event = (body.event ?? '').toString().toLowerCase();

let status = 'sent';
if (event === 'delivered') status = 'delivered';
if (['soft_bounce', 'hard_bounce', 'invalid_email', 'blocked', 'error'].includes(event)) status = 'failed';

return [{ json: { provider_message_id: providerMessageId, status } }];
